def count_simple_paths(n, m, edges):
    nodes = defaultdict(int)
    for u, v in edges:
        nodes[u] += 1
        nodes[v] += 1

    dp = [1] * (n + 1)
    for node in range(2, n + 1):
        if nodes[node - 1] > dp[node - 2]:
            dp[node] = nodes[node - 1]

    results = [0] * (n + 1)
    for v in range(n, 1, -1):
        for u in range(1, v):
            if v < u and nodes[abs(v - u) - 1] <= dp[v - 1]:
                results[v] = (results[v] + results[u] + dp[v]) % (10**9 + 7)

    return sum(results) % (10**9 + 7)

