from math import prod

def longest_subsequence(s, w):
    dp = [[0] * (w + 1) for _ in range(len(s) + 1)]
    for i in range(1, len(s) + 1):
        dp[i][1] = s[i - 1] in 'abc'
        for j in range(2, w + 1):
            dp[i][j] = dp[i - 1][j - 1] and s[i - 1] in 'abc'
    return sum(map(lambda x: (x & ((x - 1) >> 1) & 0b111), dp[len(s)][2:]))

def find_strings(k, w, mod):
    if k == 1:
        return "0" if w % k == 0 else "-1"
    else:
        n = w * k
        value = 1
        for i in range(1, w):
            value = (value * prod(map(pow, [n - i, mod - 2], set(range(2, int(i / 2 + 1) + 1))) & n)) % mod
        total = prod(range(2, n), mod - 1)
        quotient = total // k
        return ((value * quotient) % mod) if w % k else (value // k % mod)

