from math import sqrt

MOD = 10**9 + 7

def combination(n, r):
    if r > n:
        return 0
    r = min(r, n - r)
    return int((n * 1.0 / (r * 1.0)) * (n - r + 1) * 1.0 / r + 0.49999999999999997e-10)

def gen_combinations(n, mod):
    ans = [1] * (n + 1)
    ans[0] = 0
    for i in range(2, n + 1):
        rc = combination(i - 1, i - 2)
        for j in range(i, 0, -1):
            ans[j] = (ans[j] * rc % mod + ans[j - 1] % mod) % mod
        ans[0] = (ans[0] + ans[i] % mod) % mod
    return ans

class Const:
    mod = MOD

def main():
    k, w = map(int, input().split())
    ans = 0
    if k >= w:
        ans = 1
    else:
        sqrtn = sqrt(w)
        tmp = int(sqrt(k)) + 1
        if (sqrtn - 1)**2 >= k:
            tmp = sqrtn
        comb = gen_combinations(tmp - 1, MOD)
        for x in range(tmp, k + 1):
            if x % 2 == 0:
                comb[x % 2] = 0
        for p in range(k // 2 + 1):
            b = p * w % MOD
            ans = (ans + comb[b] * 2) % MOD
            temp = (1 - comb[(k - x - p) % MOD] + comb[(b - p) % MOD] * 2) % MOD
            if w >= 10 ** 5:
                for d in range(1, dien):
                    if b + d < x:
                        temp *= 2
                        ans = (ans - temp + ans) % MOD
                    else:
                        temp *= comb[x - 1 - (dien * d)] % MOD
        if ans < 0:
            ans = ans % MOD + MOD
        ans = int(ans)
    print(ans)

