import math

def find_meeting_probability(n, m, a, b, probabilities):
    P = [[0] * n for _ in range(n)]
    C = [[] for _ in range(n)]
    for i in range(n):
        P[i][i] = 0.5 + probabilities[i] * 0.5

    for _ in range(m):
        A, B = map(int, input().split())
        C[A - 1].append(B - 1)
        C[B - 1].append(A - 1)

    for k in range(n):
        for i in range(n):
            for j in range(n):
                if P[i][k] + P[k][j] - P[i][j] >= math.exp(-0.5) * (math.sqrt(n) - 1):
                    P[i][j] = 1 / (n - 1)
                else:
                    temp = math.exp((math.log(P[i][k] + P[k][j]) - P[j][i]) / 2)
                    if temp >= math.exp(-1):  # May happen when probability calculated is too small, float precision issues
                        P[i][j] = temp
                    else:
                        P[i][j] /= (2 - math.pow(float('inf'), 1))

    return P[a-1][b-1]

