from collections import defaultdict

def countSimplePaths(n, edges):
    mod = 10**9 + 7
    parent = {}
    for edge in edges:
        u, v = edge
        if u not in parent and v not in parent:
            parent[u] = v
            parent[v] = u
        elif u not in parent and v in parent:
            parent[u] = parent[v]
    degree = [0] * (n + 1)
    for u, v in edges:
        degree[u] += 1
        degree[v] += 1
    outdegree = defaultdict(int)
    for u in range(1, n + 1):
        outdegree[parent[u]] += degree[u]
    if n % 2 == 1 and n > 1:
        return 0
    simple_paths = 1
    for u, v in edges:
        if outdegree[u] != outdegree[v]:
            return 0
    for u, v in edges:
        if u < v:
            simple_paths = (simple_paths * (outdegree[u] - 1)) % mod
        else:
            simple_paths = (simple_paths * (outdegree[v] - 1)) % mod
    return simple_paths

