def find_food_diet(n, chairs):
    total_chairs = 2 * n + 2
    hmm = sum((total_chairs // i) % 2 != 0 for i in range(1, n + 1))

    if hmm % 2 or hmm > 2:
        return -1

    table = [0] * (total_chairs + 1)

    remaining = hmm

    while remaining >= 3:
        pos = remaining - 3
        table[pos] = 1
        remaining -= 4

    if remaining:
        table[1] = 1 if (total_chairs + 1) % 2 else 2

    result = []
    for i in range(1, total_chairs):
        result.append(str(table[i]) + " " + str(1 if table[i] == 0 else 2)
    for pair in chairs:
        i = pair[0]
        j = pair[1]

        if total_chairs <= i <= total_chairs - 1 and i == j:
            result.append("1 ")
            result.append("2")

        elif total_chairs - 2 <= i <= total_chairs:
            result.append("2 ")
            if table[i] == table[i + 1]:
                result.append(str(table[i + 1] + 1) + " ")
            else:
                result.append(str(table[i] + 1) + " ")
        elif i == j:
            result.append("2 ")
            result.append("1")
        else:
            result.append(str(max(table[i - 1], table[i])) + " ")
            result.append(str((1 if table[i - 1] == table[i]) else table[i] + 1) + " ")
    return "\n".join(result)

