from sympy import divisors, factorint

def kXx(w: int, k: int) -> int:
    if k % w == 0:
        return k
    return -1

def main(k: int, w: int) -> int:
    if k >= w * (w - 1) // 2:
        lcm = k * (w - 1) // w
        result = kXx(w, lcm) + kXx(w, lcm // 2)
    elif k % 2:
        result = kXx(w, k // 2) + kXx(w, k // 2 + 1)
    else:
        result = k // 2

    egs = {k % m for m in range(2*k, k*k + 1, k)}
    if egs <= set(range(1, (w-1) // 2 + 1)):
        m = set(d for d in divisors(w - 1) if d <= (w-1) // 2 and d % 2 == 0) & egs
    else:
        m = (w-1) // 2

    return tuple(map(lambda x: kXx(w, x), m))[-1] if m > 0 else -1

