MOD = 10**9 + 7

def multiply(x, y):
    return ((x % MOD) * (y % MOD)) % MOD

def power(x, k):
    res = 1 % MOD
    y = x % MOD
    while k:
        if k % 2:
            res = multiply(res, y)
        y = multiply(y, y)
        k = k // 2
    return res

def calculate_probability(area, charge, anomaly):
    r_start, c_start, r_end, c_end = area
    total_cells = (r_start - 1) * (c_start - 1)
    for i in range(r_end, r_start, -1):
        if charge[i % (r_end - r_start + 1)] % 2 == 1:
            charge[r_start] -= 1
    for j in range(c_end, c_start, -1):
        if (r_start - 1) == (r_end - 1):
            if j == c_start:
                # For unit cell containing anomaly always carry the negative fraction
                if charge[(r_start - 1) // 2] % 2 == 1:
                    charge[r_start] -= 1
            elif (r_start - 1) % 2 == 1 and (j % 2) == 1:
                charge[r_start - 1] -= 1
                charge[r_start] -= 1
    for i in range(r_start, r_end):
        if charge[(i - 1) % (r_start - r_end + 1)] % 2 == 1:
            charge[i] -= 1
    for j in range(c_end, c_start, -1):
        if j % 2 == 1:
            charge[(r_start - 1) // 2] -= 1

    factor = 1
    if (r_start - 1) != (r_end - 1):
        factor = (1 << ((r_end + 1) - r_start - c_end)) % MOD
    total_routes = 0
    for i in range(1, r_end):
        dist2 = ((r_end - 1) - i) * ((r_end - 1) - i)
        total_routes += (factor // (1 << (dist2 + 1))) % MOD * power(2, total_cells - i) % MOD
    total_routes = power(total_routes, 2)**2 % MOD
