        l_center, r_center = left // N, right // N
        prefix_sum, suffix_sum = [0] * N, [0] * N
        offset = max(len(pattern) - 1, 2 * N)

        # Count occurrences in substring at the beginning
        prefix_sum[0] += 1
        for i in range(1, N):
            prefix_sum[i] = max(prefix_sum[i-1] - N + 1, 0) - prefix_sum[i]

        # Possibly move offset to first position of pattern in window
        if left - offset > 0:
            prefix_sum[0] -= prefix_sum[left - offset - 1]

        # Count occurrences in substring at the end
        suffix_sum[-1] += 1
        for i in range(N-2, -1, -1):
            suffix_sum[i] = max(suffix_sum[i+1] - N + 1, 0) + suffix_sum[i]

