import sys

class UnionFind:
    def __init__(self, n):
        self.parent = list(range(n))
        self.size = [1 for _ in range(n)]
        self.components = n

    def find(self, x):
        if self.parent[x] != x:
            self.parent[x] = self.find(self.parent[x])
        return self.parent[x]

    def union(self, x, y):
        root_x = self.find(x)
        root_y = self.find(y)
        if root_x != root_y:
            if self.size[root_x] > self.size[root_y]:
                root_x, root_y = root_y, root_x
            self.union(root_x, root_y)
            self.size[root_y] += self.size[root_x]
            self.components -= 1

    def count(self):
        return self.components

def solve(test_case):
    n = int(sys.stdin.readline().strip())
    adj = [[] for _ in range(n)]
    for _ in range(n-1):
        u, v = map(int, sys.stdin.readline().strip().split())
        u -= 1
        v -= 1
        adj[u].append(v)
        adj[v].append(u)

    vertices = sys.stdin.readline().strip()
    vertices = list(map(int, vertices.split()))

    disjoint_sets = UnionFind(n)

    for i in range(n):
        disjoint_sets.union(i, adj[i][0])

    greedys_zero = []
    greedy_ds = []
    for j in range(len(vertices)):
        if vertices[j] == 0:
            greedys_zero.append((disjoint_sets.find(j), j))
        elif disjoint_sets.find(j) > 0:
            greedy_ds.append((disjoint_sets.count(), disjoint_sets.find(j), j))

    greedys_zero.sort(reverse=True)
    greedy_ds.sort(reverse=True)

    operations = 0
    for edge_weight, children, vertex_id in greedys_zero + greedy_ds:
        if not disjoint_sets.find(vertex_id):
            operations += 1
            for child in adj[vertex_id]:
                disjoint_sets.union(vertex_id, child)
        else:
            for child in adj[vertex_id]:
                if disjoint_sets.find(child) > 0:
                    operations += 1
                    disjoint_sets.union(vertex_id, child)

    return operations

