from collections import defaultdict

def calculate_paths(n, m, edges):
    graph = defaultdict(list)
    for u, v in edges:
        graph[u].append(v)
        graph[v].append(u)

    path_count = [1] * (n + 1)

    def dfs(node, parent, path_count):
        for neighbor in graph[node]:
            if neighbor != parent:
                path_count[neighbor] = (path_count[node] * (len(graph[neighbor]) - 1)) % (10**9 + 7)
                dfs(neighbor, node, path_count)

    dfs(1, -1, path_count)

    if n % 2 == 0:
        path_count[1] = path_count[1] * (n // 2 - 1) % (10**9 + 7)

    return sum(path_count) % (10**9 + 7)

