from collections import deque

def catalan(i, s):
    dp = [0] * (i + 1)
    dp[0] = dp[1] = 1
    q = deque([i])
    while q:
        n = len(q)
        for _ in range(n):
            k = q.popleft()
            if s[k] == '(':
                dp[k] = dp[k-1] + dp[k]
            else:
                dp[k] = 2 * dp[k]
            extend_i = (n-1 - k) % len(q)
            for _ in range(k):
                q.append((k+extend_i) % len(q))
    return dp[i]

def largest_beauty(n, s):
    total_beauty = -1
    i, j = 0, -1
    while i < n and j < n:
        if total_beauty < 0 or (total_beauty == 0 and s[i] == '('):
            total_beauty = 0
            total_jug = 0
            for k in range(i):
                total_beauty += s[k] == '('
            while total_jug == 0 or total_jug <= total_beauty:
                while total_jug == 0 and j < n:
                    total_jug += s[j] == '('
                    j += 1
                total_beauty -= s[j] == ')'
        j += 1
        if total_beauty < 0:
            i += 1
    return max(total_beauty, 0)

