import sys
from math import factorial

def bell_manteuffel(n):
    result = 0
    for k in range(0, n+1):
        result += factorial(n) // (factorial(k) * factorial(n-k))
    return result

def calculate_probability(n, m_a, m_b, room_a, room_b, probabilities):
    frequency = bell_manteuffel(n * (n-1) // 2)

    combinations = bell_manteuffel(n)

    probability_a_to_b = 0
    for i in range(1, n+1):
        for j in range(1, n+1):
            if i != j and i != room_a and j != room_b and i != room_b and j != room_a:
                probability_of_paths = 1
                for _ in range(m_a - 1 if i == room_a else 1):
                    probability_of_paths *= (1 - probabilities[i-1])
                if m_b > 1:
                    for _ in range(m_b - 1 if j == room_b else 1):
                        probability_of_paths *= (1 - probabilities[j-1])
                else:
                    probability_of_this_path = probabilities[j-1]
                probability_a_to_b += probability_of_paths * frequencies[i] // combinations * (1 - probability_of_paths + frequencies[j] // combinations)

    return probability_a_to_b / frequency

def main():
    n, m, roomA, roomB = map(int, input().split())
    room_dict = {}

    for _ in range(m):
        from_room, to_room = map(int, input().split())
        if from_room in room_dict:
            room_dict[from_room].append(to_room)
        else:
            room_dict[from_room] = [to_room]

    probabilities = [float(i) / 100.0 for i in input().split()]

    frequencies = [bell_manteuffel(i) for i in room_dict.keys()]
    probabilities = tuple(probabilities)

    rooms_result = calculate_probability(n, *probabilities, roomA, roomB, room_dict)
    print(' '.join(map(str, rooms_result)))

